import{_ as t,o as a,c as d,ag as o}from"./chunks/framework.Dx86EdC1.js";const u=JSON.parse('{"title":"Template Surat","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-pengguna/template-surat.md","filePath":"panduan-pengguna/template-surat.md","lastUpdated":1791382762000}'),r={name:"panduan-pengguna/template-surat.md"};function n(l,e,i,c,s,m){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="template-surat" tabindex="-1">Template Surat <a class="header-anchor" href="#template-surat" aria-label="Permalink to &quot;Template Surat&quot;">​</a></h1><p>Menu <strong>E-Surat → Template Surat</strong> (<code>/admin/letter-templates</code>) mengelola format surat baku desa.</p><h2 id="template-bawaan-seeder" tabindex="-1">Template Bawaan (Seeder) <a class="header-anchor" href="#template-bawaan-seeder" aria-label="Permalink to &quot;Template Bawaan (Seeder)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kode</th><th>Nama</th></tr></thead><tbody><tr><td><code>SKTM</code></td><td>Surat Keterangan Tidak Mampu</td></tr><tr><td><code>SKCK</code></td><td>Surat Pengantar SKCK</td></tr><tr><td><code>DOMISILI</code></td><td>Surat Keterangan Domisili</td></tr><tr><td><code>SKU</code></td><td>Surat Keterangan Usaha</td></tr><tr><td><code>SKPWNI</code></td><td>Surat Keterangan Pindah (SKPWNI)</td></tr></tbody></table><h2 id="komponen-template" tabindex="-1">Komponen Template <a class="header-anchor" href="#komponen-template" aria-label="Permalink to &quot;Komponen Template&quot;">​</a></h2><ul><li><strong>Kode &amp; Nama</strong> — kode dipakai pada nomor surat.</li><li><strong>Format Nomor</strong> (<code>number_format</code>) — pola placeholder nomor otomatis.</li><li><strong>Konten (<code>content_template</code>)</strong> — badan surat HTML dengan placeholder dinamis.</li><li><strong>Field tambahan</strong> — isian wajib saat permohonan (mis. SKU: nama usaha, lokasi usaha, sejak kapan).</li><li><strong>Status aktif</strong> — template nonaktif tidak muncul di form warga.</li></ul><h2 id="placeholder-konten" tabindex="-1">Placeholder Konten <a class="header-anchor" href="#placeholder-konten" aria-label="Permalink to &quot;Placeholder Konten&quot;">​</a></h2><p>Diisi otomatis sistem saat surat dibuat (<code>LetterService::parseTemplateContent</code>):</p><table tabindex="0"><thead><tr><th>Placeholder</th><th>Isi</th></tr></thead><tbody><tr><td><code>[NAMA_DESA]</code>, <code>[NAMA_KECAMATAN]</code>, <code>[NAMA_KABUPATEN]</code>, <code>[NAMA_PROVINSI]</code></td><td>Dari Pengaturan Situs</td></tr><tr><td><code>[NAMA]</code>, <code>[NIK]</code>, <code>[NO_KK]</code></td><td>Data pemohon</td></tr><tr><td><code>[TEMPAT_TANGGAL_LAHIR]</code>, <code>[JENIS_KELAMIN]</code>, <code>[AGAMA]</code>, <code>[STATUS_KAWIN]</code></td><td>Biodata</td></tr><tr><td><code>[PENDIDIKAN]</code>, <code>[PEKERJAAN]</code>, <code>[KEWARGANEGARAAN]</code></td><td>Biodata</td></tr><tr><td><code>[ALAMAT]</code>, <code>[RT]</code>, <code>[RW]</code>, <code>[DUSUN]</code></td><td>Dari KK</td></tr><tr><td><code>[KEPERLUAN]</code></td><td>Keperluan pemohon</td></tr><tr><td><code>[NOMOR_SURAT]</code>, <code>[TANGGAL_SURAT]</code></td><td>Hasil generate</td></tr></tbody></table><p>Placeholder field tambahan (mis. <code>[NAMA_USAHA]</code>) ditambahkan otomatis sesuai definisi field template.</p><h2 id="placeholder-format-nomor" tabindex="-1">Placeholder Format Nomor <a class="header-anchor" href="#placeholder-format-nomor" aria-label="Permalink to &quot;Placeholder Format Nomor&quot;">​</a></h2><p>Format nomor surat (<code>LetterService::generateLetterNumber</code>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{klasifikasi}/{nomor:3}/{kode}/Ds/{tahun}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Placeholder</th><th>Arti</th></tr></thead><tbody><tr><td><code>{klasifikasi}</code></td><td>Kode klasifikasi bidang surat</td></tr><tr><td><code>{nomor}</code> / <code>{nomor:N}</code></td><td>Nomor urut surat disetujui tahun berjalan, padding <code>N</code> digit (default 3)</td></tr><tr><td><code>{kode}</code></td><td>Kode template surat</td></tr><tr><td><code>{bulan}</code>, <code>{bulan_romawi}</code>, <code>{tahun}</code></td><td>Tanggal penerbitan</td></tr><tr><td><code>{desa}</code></td><td>Kode desa (setting <code>letter_village_code</code>)</td></tr></tbody></table><h2 id="membuat-template-baru" tabindex="-1">Membuat Template Baru <a class="header-anchor" href="#membuat-template-baru" aria-label="Permalink to &quot;Membuat Template Baru&quot;">​</a></h2><ol><li>Klik <strong>Tambah Template</strong>.</li><li>Isi kode unik, nama, format nomor, dan konten HTML dengan placeholder di atas.</li><li>Tambahkan definisi field tambahan bila perlu (nama, label, tipe input, wajib/tidak).</li><li><strong>Preview</strong> dulu via tombol <em>preview</em> (<code>/admin/letter-templates/{id}/preview</code>) sebelum mengaktifkan.</li><li>Aktifkan template agar tersedia bagi warga.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Selalu uji hasil PDF: pastikan placeholder terisi semua (tanda <code>-</code> berarti data warga belum lengkap — lengkapi dulu di modul Penduduk).</p></div>',17)])])}const h=t(r,[["render",n]]);export{u as __pageData,h as default};
